using System;using System.IO;using System.Linq;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;
namespace IdleIntelligence.Tests {
 public sealed class StorageTests {
 [Test]public void ExplicitRecoveryPreservesCorruptOriginalPendingAndBackupAndRejectsChangedPreview(){string dir=Path.Combine(Path.GetTempPath(),"unity-recovery-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{string path=Path.Combine(dir,"save.json"),export=Path.Combine(dir,"export.json");var codec=new UnitySaveCodec();var store=new AtomicSaveStore(path,codec);var s=store.Load(1000000).State;store.Save(s);s=Game.Tap(s,s.SavedAt);store.Save(s);store.Export(s,export);Assert.Throws<IOException>(()=>store.Export(s,export));string original="corrupt preserved main",pending="interrupted pending";File.WriteAllText(path,original);File.WriteAllText(path+".pending",pending);var locked=new AtomicSaveStore(path,codec);Assert.That(locked.Load(s.SavedAt).Writable,Is.False);var candidate=locked.Inspect(export);Assert.That(candidate.Valid,Is.True,candidate.Message);File.AppendAllText(export," ");Assert.Throws<InvalidOperationException>(()=>locked.Recover(export,candidate.Hash));candidate=locked.Inspect(export);var restored=locked.Recover(export,candidate.Hash);Assert.That(restored.Taps,Is.EqualTo(s.Taps));Assert.That(Directory.GetFiles(dir,"*-original-*").Any(f=>File.ReadAllText(f)==original));Assert.That(Directory.GetFiles(dir,"*-original-*").Any(f=>File.ReadAllText(f)==pending));Assert.That(File.Exists(path+".pending"),Is.False);locked.Save(restored);Assert.That(new AtomicSaveStore(path,codec).Load(restored.SavedAt).Writable,Is.True);}finally{Directory.Delete(dir,true);}}
 [Test]public void ValidExternalReplacementIsAlsoProtected(){string dir=Path.Combine(Path.GetTempPath(),"unity-valid-external-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{string path=Path.Combine(dir,"save.json");var store=new AtomicSaveStore(path,new UnitySaveCodec());var s=store.Load(1000000).State;store.Save(s);var other=new AtomicSaveStore(path,new UnitySaveCodec());var n=other.Load(1000000).State;n=Game.Tap(n,n.SavedAt);other.Save(n);string original=File.ReadAllText(path);Assert.Throws<IOException>(()=>store.Save(s));Assert.That(File.ReadAllText(path),Is.EqualTo(original));}finally{Directory.Delete(dir,true);}}
 [Test]public void MeasuredReturnIsGrossBoundedAndReloadDoesNotRewardAgain(){var s=Game.New(1000000);s=Game.Buy(s,"calculator");var before=s.Copy();double seconds=Game.OfflineLimit(s)+123;var outcome=Game.AdvanceMeasured(s,s.SavedAt+seconds*1000);var n=outcome.State;ReturnReceipt.Attach(s,n,outcome.Report);Assert.That(n.Return.elapsed,Is.EqualTo(seconds));Assert.That(n.Return.credited,Is.EqualTo(Game.OfflineLimit(s)));Assert.That(n.Return.discarded,Is.EqualTo(123));Assert.That(ScientificNumber.FromData(n.Return.credits).CompareTo(Game.Income(before).Times(Game.OfflineLimit(before))),Is.EqualTo(0));var codec=new UnitySaveCodec();var reload=codec.Decode(codec.Encode(StateData.From(n))).ToState();var again=Game.AdvanceMeasured(reload,reload.SavedAt);Assert.That(again.Report.Credited,Is.Zero);Assert.That(again.State.Credits.CompareTo(n.Credits),Is.Zero);ReturnReceipt.Attach(reload,again.State,again.Report);Assert.That(again.State.Return.id,Is.EqualTo(n.Return.id));Assert.That(s.Credits.CompareTo(before.Credits),Is.Zero);}
 }
}
